package com.ryu.forkliftdiagnostic.ui;
import android.app.Activity; import android.os.Bundle; import android.widget.*; import com.ryu.forkliftdiagnostic.core.AssetJson; import org.json.*;
public class InfoActivity extends Activity{public void onCreate(Bundle b){super.onCreate(b);String mode=getIntent().getStringExtra("mode");LinearLayout body=Ui.page(this,title(mode));if("manual".equals(mode)){try{JSONObject j=AssetJson.read(this,"v20/legacy/manual_library_catalog.json");JSONArray docs=j.optJSONArray("documents");body.addView(Ui.text(this,"Legacy catalog 보존: "+(docs==null?0:docs.length())+" records",16,true));}catch(Exception e){body.addView(Ui.text(this,"Catalog 읽기 실패: "+e,14,true));}body.addView(Ui.text(this,"문서 검색됨과 모델별 정규화 완료는 별도 상태입니다. 다른 제조사 자료를 두산 그래프에 자동 연결하지 않습니다.",15,false));}else if("parts".equals(mode))body.addView(Ui.text(this,"부품번호·가격·공임은 terminal 진단 결과 뒤에만 연결됩니다.",16,true));else body.addView(Ui.text(this,"오프라인 로컬 저장소 구조가 분리되어 있습니다. 이 CLEAN ALPHA에서는 조회 구조만 제공하며 데이터 입력은 다음 gate 대상입니다.",16,false));}private String title(String m){if("manual".equals(m))return "매뉴얼 라이브러리";if("parts".equals(m))return "부품·가격·공임";if("history".equals(m))return "정비 이력";return "내 현장 경험";}}
